package main

import (
	"bytes"
	"fmt"
	"go/format"
	"slices"
	"strconv"
	"strings"
)

const header = "// Code generated by provider/internal/schemagen from agent-schema.json of " +
	"github.com/docker/docker-agent %s. DO NOT EDIT.\n// Regenerate with `make generate_config_types`.\n\n"

// emitTypes renders the Go source of the config types.
func emitTypes(g *generator, version string) ([]byte, error) {
	var b bytes.Buffer
	fmt.Fprintf(&b, header, version)
	b.WriteString("package render\n\nimport \"github.com/pulumi/pulumi-go-provider/infer\"\n\n")
	for _, t := range g.sortedTypes() {
		writeComment(&b, "", t.name+" is generated from `"+t.path+"`. "+typeDoc(t))
		fmt.Fprintf(&b, "type %s struct {\n", t.name)
		for _, f := range t.fields {
			tag := fmt.Sprintf(`pulumi:"%s%s" yaml:"%s"`, f.pulumi, optional(f), f.yamlKey)
			if f.render != "" {
				tag += fmt.Sprintf(` render:"%s"`, f.render)
			}
			fmt.Fprintf(&b, "\t%s %s `%s`\n", f.goName, f.goType, tag)
		}
		b.WriteString("}\n\n")
		fmt.Fprintf(&b, "// Annotate describes %s for the Pulumi schema.\n", t.name)
		fmt.Fprintf(&b, "func (x *%s) Annotate(a infer.Annotator) {\n", t.name)
		if t.name != "Document" {
			// Document is embedded in the resource inputs; only its fields are described.
			fmt.Fprintf(&b, "\ta.Describe(&x, %s)\n", strconv.Quote(typeDoc(t)))
		}
		for _, f := range t.fields {
			if f.desc != "" {
				fmt.Fprintf(&b, "\ta.Describe(&x.%s, %s)\n", f.goName, strconv.Quote(f.desc))
			}
			if f.setDef != "" {
				fmt.Fprintf(&b, "\ta.SetDefault(&x.%s, %s)\n", f.goName, f.setDef)
			}
		}
		b.WriteString("}\n\n")
	}
	return format.Source(b.Bytes())
}

func typeDoc(t *goType) string {
	d := strings.TrimSpace(t.desc)
	if o, ok := descriptions[t.path]; ok {
		d = o
	}
	if d == "" {
		d = fallbackDescriptions[t.path]
	}
	if d == "" {
		d = "The `" + t.path + "` object of a docker-agent configuration."
	}
	if t.union {
		var names []string
		for _, f := range t.fields {
			names = append(names, "`"+f.pulumi+"`")
		}
		d = sentence(d) + "Set " + strings.Join(names, " and/or ") + "; they are rendered together into one value."
	}
	return d
}

func optional(f *goField) string {
	if f.required {
		return ""
	}
	return ",optional"
}

// writeComment writes text as a wrapped Go comment.
func writeComment(b *bytes.Buffer, indent, text string) {
	words := strings.Fields(text)
	line := indent + "//"
	for _, w := range words {
		if len(line)+1+len(w) > 100 && line != indent+"//" {
			b.WriteString(line + "\n")
			line = indent + "//"
		}
		line += " " + w
	}
	b.WriteString(line + "\n")
}

// emitRenderVersion renders the generated constants of package render.
func emitRenderVersion(version, configVersion string) ([]byte, error) {
	var b bytes.Buffer
	fmt.Fprintf(&b, header, version)
	b.WriteString("package render\n\n")
	b.WriteString("// DefaultConfigVersion is the docker-agent config schema version rendered when none is set: the\n")
	b.WriteString("// highest value of the `version` enum in agent-schema.json.\n")
	fmt.Fprintf(&b, "const DefaultConfigVersion = %q\n", configVersion)
	return format.Source(b.Bytes())
}

// emitValidateConstants renders the generated constants of package validate.
func emitValidateConstants(version, configVersion string, toolsets, providers []string) ([]byte, error) {
	var b bytes.Buffer
	fmt.Fprintf(&b, header, version)
	b.WriteString("package validate\n\n")
	b.WriteString("// DockerAgentVersion is the docker-agent library version configurations are validated\n")
	b.WriteString("// against: the version of github.com/docker/docker-agent in provider/go.mod. It is also\n")
	b.WriteString("// written to the `io.docker.agent.version` annotation of pushed artifacts.\n")
	fmt.Fprintf(&b, "const DockerAgentVersion = %q\n\n", version)
	b.WriteString("// LatestConfigVersion is the highest config schema version docker-agent " + version + " understands.\n")
	fmt.Fprintf(&b, "const LatestConfigVersion = %q\n\n", configVersion)
	b.WriteString("// ToolsetTypes are the toolset types docker-agent " + version + " registers\n")
	b.WriteString("// (toolsets.DefaultToolsetCreators, as listed by `docker agent toolsets`). docker-agent's parser\n")
	b.WriteString("// does not reject unknown types, so the provider checks them itself.\n")
	fmt.Fprintf(&b, "var ToolsetTypes = %s\n\n", goStrings(toolsets))
	b.WriteString("// ProviderTypes are the model provider types docker-agent " + version + " implements natively\n")
	b.WriteString("// (providers.DefaultFactories without the openai_* API flavours). Built-in aliases (mistral,\n")
	b.WriteString("// openrouter, ...) and custom `providers:` entries resolve to one of these. The OpenAI API\n")
	b.WriteString("// flavours `openai_chatcompletions` and `openai_responses` are served by the openai implementation.\n")
	fmt.Fprintf(&b, "var ProviderTypes = %s\n", goStrings(providers))
	return format.Source(b.Bytes())
}

func goStrings(vals []string) string {
	vals = slices.Sorted(slices.Values(vals))
	q := make([]string, len(vals))
	for i, v := range vals {
		q[i] = strconv.Quote(v)
	}
	return "[]string{\n" + strings.Join(q, ",\n") + ",\n}"
}
